---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- Laptop screen (only supports 60 Hz)
hl.monitor({
    output   = "eDP-1",
    mode     = "1920x1080@60",
    position = "0x0",
    scale    = 1,
})

-- Samsung LS22F31x on HDMI, to the right of the laptop, at 120 Hz
hl.monitor({
    output   = "HDMI-A-1",
    mode     = "1920x1080@120",
    position = "1920x0",   -- right after the laptop screen (1920 wide at scale 1)
    scale    = 1,
})

-- Anything else you plug in: best mode, placed automatically
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})


