-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
    -- let portals / dbus services see this Wayland session (dark mode, file pickers, screen share)
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_TYPE HYPRLAND_INSTANCE_SIGNATURE"
             .. " && systemctl --user start hyprland-session.target")
    hl.exec_cmd(os.getenv("HOME") .. "/.local/bin/gtk-theme-switch gruvbox")
    hl.exec_cmd(os.getenv("HOME") .. "/.local/bin/wallpaper --restore")
    hl.exec_cmd("waybar")
    hl.exec_cmd("mako")
    hl.exec_cmd("hypridle")
    -- equalizer runs in the background so the EQ is always applied (only if installed)
    hl.exec_cmd("command -v easyeffects >/dev/null && easyeffects --gapplication-service")
    hl.exec_cmd("/usr/libexec/hyprpolkitagent")
end)

hl.on("hyprland.shutdown", function ()
    hl.exec_cmd("systemctl --user stop hyprland-session.target")
end)


