-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        -- small gaps between windows (Super+Shift+Backspace toggles them)
        gaps_in  = gaps.inner,
        gaps_out = gaps.outer,

        border_size = 2,

        col = {
            active_border   = "rgb(" .. gb.fg .. ")",
            inactive_border = "rgb(" .. gb.bg1 .. ")",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        -- fully square, no effects
        rounding = 0,

        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = { enabled = false },
        blur   = {
            enabled           = true,
            size              = 6,
            passes            = 2,      -- 2 passes: soft blur, still cheap
            new_optimizations = true,
            xray              = false,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Short, snappy animations: pretty but never in the way
