-- Omarchy keybinds, adapted to this setup (kitty, helium, nautilus, rofi).
-- Super+K shows them all.

local HOME = os.getenv("HOME")

-- bind(keys, description, action [, opts]) — action is a dispatcher,
-- a function, or a shell command string
local function bind(keys, desc, action, opts)
    if type(action) == "string" then action = hl.dsp.exec_cmd(action) end
    opts = opts or {}
    opts.description = desc
    hl.bind(keys, action, opts)
end

