-- Workspaces (number row, works on any keyboard layout)
for ws = 1, 10 do
    local key = "code:" .. tostring(ws + 9)
    bind("SUPER + " .. key,               "Switch to workspace " .. ws,          hl.dsp.focus({ workspace = tostring(ws) }))
    bind("SUPER + SHIFT + " .. key,       "Move window to workspace " .. ws,     hl.dsp.window.move({ workspace = tostring(ws) }))
    bind("SUPER + SHIFT + ALT + " .. key, "Move window silently to workspace " .. ws, hl.dsp.window.move({ workspace = tostring(ws), follow = false }))
end
