-- Resize with - and =
for _, r in ipairs({ { "", 100, "" }, { "ALT + ", 25, " a little" }, { "CTRL + ", 300, " a lot" } }) do
    local mod, n, sfx = r[1], r[2], r[3]
    bind("SUPER + " .. mod .. "code:20",         "Expand window left" .. sfx, hl.dsp.window.resize({ x = -n, y = 0, relative = true }))
    bind("SUPER + " .. mod .. "code:21",         "Shrink window left" .. sfx, hl.dsp.window.resize({ x = n,  y = 0, relative = true }))
    bind("SUPER + SHIFT + " .. mod .. "code:20", "Shrink window up" .. sfx,   hl.dsp.window.resize({ x = 0, y = -n, relative = true }))
    bind("SUPER + SHIFT + " .. mod .. "code:21", "Expand window down" .. sfx, hl.dsp.window.resize({ x = 0, y = n,  relative = true }))
end
bind("SUPER + mouse:272",            "Move window",           hl.dsp.window.drag(),   { mouse = true })
bind("SUPER + mouse:273",            "Resize window",         hl.dsp.window.resize(), { mouse = true })

